  <style>
    :root {
      --paper: #f2eee4;
      --paper-light: #faf7f0;
      --ink: #121210;
      --muted: #605c53;
      --red: #d42a1e;
      --red-bright: #ff5a4c;
      --blue: #1d4e9e;
      --blue-bright: #82a8ff;
      --yellow: #f4c430;
      --yellow-bright: #ffd84d;
      --grey: #8a867c;
      --line: 2px solid var(--ink);
      --sans: "Archivo", "Helvetica Neue", Arial, sans-serif;
      --mono: "DM Mono", "Courier New", monospace;
      --pad: clamp(22px, 4.6vw, 72px);
    }

    *,
    *::before,
    *::after { box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      margin: 0;
      background: var(--paper);
      color: var(--ink);
      font-family: var(--sans);
      font-size: 17px;
      line-height: 1.55;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    ::selection { background: var(--red); color: #fff; }

    a { color: inherit; }

    img, svg { display: block; max-width: 100%; }

    :focus-visible {
      outline: 3px solid var(--blue);
      outline-offset: 4px;
    }

    .sr-only {
      position: absolute;
      width: 1px; height: 1px;
      padding: 0; margin: -1px;
      overflow: hidden;
      clip: rect(0 0 0 0);
      white-space: nowrap;
      border: 0;
    }

    .skip {
      position: absolute;
      top: -100px; left: 16px;
      z-index: 200;
      padding: 12px 18px;
      background: var(--ink);
      color: var(--paper);
      font-family: var(--mono);
      font-size: 12px;
      text-decoration: none;
    }
    .skip:focus { top: 12px; }

    /* ---------- header ---------- */

    .site-head {
      position: sticky;
      top: 0;
      z-index: 80;
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      align-items: center;
      gap: 24px;
      min-height: 72px;
      padding: 0 var(--pad);
      background: color-mix(in srgb, var(--paper) 94%, transparent);
      border-bottom: var(--line);
    }

    @supports (backdrop-filter: blur(8px)) {
      .site-head { backdrop-filter: blur(10px); }
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      justify-self: start;
      text-decoration: none;
      font-family: var(--mono);
      font-size: 11px;
      letter-spacing: .16em;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .brand-mark {
      position: relative;
      width: 30px;
      height: 30px;
      flex: 0 0 30px;
      background: var(--paper-light);
      border: 2px solid var(--ink);
      overflow: hidden;
    }
    .brand-mark::before {
      content: "";
      position: absolute;
      top: 0; right: 0;
      width: 13px; height: 13px;
      background: var(--red);
      border-left: 1.5px solid var(--ink);
